/**
 * Furniture catalogue — real measured meshes.
 *
 * The asset list is generated by `scripts/build-furniture-catalog.mjs` from the
 * geometry itself, so these numbers are measurements, not intentions. Every layer
 * of the product reads the same numbers:
 *
 *   2D plan          draws a `widthM` × `depthM` rectangle
 *   axonometric      extrudes that rectangle
 *   A4 study sheet   prints it at a physical scale
 *   3D view          fits the real mesh onto that footprint
 *
 * If those four disagreed the drawing would be a lie, so
 * `furnitureAssets.test.ts` re-measures each shipped GLB and fails if any layer
 * has drifted.
 *
 * The meshes themselves are Khronos glTF sample assets under CC0 or CC-BY 4.0,
 * normalised to metres and compressed with Meshopt + WebP. They are fetched on
 * demand: the 3D chunk stays lazy, so none of this enters first paint. A piece
 * whose footprint falls outside a mesh's band draws its measured box, which is
 * honest and is what the plan already showed.
 */

import type { FurnitureKind } from '../types'
import { GENERATED_FURNITURE_ASSETS } from './furnitureCatalog.generated'

/**
 * Inclusive `[min, max]` footprint window, in metres, that a mesh may be drawn
 * at. Outside it the mesh is not the object being drawn and the box takes over.
 */
export type FootprintBand = { w: [number, number]; d: [number, number] }

export interface FurnitureAsset {
  /** Stable id, referenced by saved plans and share links. */
  id: string
  /**
   * What the mesh actually is. Distinct from `FurnitureKind`: a mesh is a
   * *sheen chair*, and it serves the `chair` kind across a range of footprints.
   */
  shape: 'seat' | 'sofa' | 'decor'
  /** Kinds this mesh is allowed to stand in for. */
  serves: readonly FurnitureKind[]
  /** Footprint window where this mesh still reads as its own shape. */
  bandM: FootprintBand
  label: string
  /** Measured footprint in metres. The 2D layers draw this. */
  widthM: number
  depthM: number
  heightM: number
  /** Path under `public/`, resolved against the deployment base. */
  file: string
  /** Byte size of the shipped file, asserted against disk by the test suite. */
  bytes: number
  credit: string
  license: string
  source: string
}

export const FURNITURE_ASSETS: readonly FurnitureAsset[] = GENERATED_FURNITURE_ASSETS

/** Total catalogue weight, lazy-loaded and never part of the first paint. */
export const FURNITURE_CATALOGUE_BYTES = FURNITURE_ASSETS.reduce((sum, asset) => sum + asset.bytes, 0)

/**
 * Byte ceiling for the whole catalogue. Asserted by the test suite: growing past
 * this means furniture is starting to cost the user a real download.
 */
export const FURNITURE_BUDGET_BYTES = 3_500_000

/** Resolve a catalogue path against the deployment base. */
export function furnitureAssetUrl(file: string, base = import.meta.env.BASE_URL): string {
  return `${base}${base.endsWith('/') ? '' : '/'}${file}`
}

/**
 * Uniform scale mapping an asset's own footprint onto the drawn footprint. The
 * smaller ratio wins so a mesh is never stretched to overhang the rectangle the
 * 2D plan draws.
 */
export function fitScaleFor(asset: FurnitureAsset, widthM: number, depthM: number): number {
  if (asset.widthM <= 0 || asset.depthM <= 0) return 1
  return Math.min(widthM / asset.widthM, depthM / asset.depthM)
}

/** Is a drawn footprint inside the window this mesh may be drawn at? */
export function servesFootprint(asset: FurnitureAsset, widthM: number, depthM: number): boolean {
  return (
    widthM >= asset.bandM.w[0] &&
    widthM <= asset.bandM.w[1] &&
    depthM >= asset.bandM.d[0] &&
    depthM <= asset.bandM.d[1]
  )
}

/** Every asset that could serve a given kind, in catalogue order. */
export function furnitureAssetsForKind(kind: FurnitureKind): readonly FurnitureAsset[] {
  return FURNITURE_ASSETS.filter((asset) => asset.serves.includes(kind))
}

export function furnitureAssetById(id: string | undefined): FurnitureAsset | null {
  if (!id) return null
  return FURNITURE_ASSETS.find((asset) => asset.id === id) ?? null
}

/**
 * Pick the mesh for one furniture piece, or `null` to draw its measured box.
 *
 * `null` is the honest answer, not a failure. It is returned when the kind has
 * no real geometry at all (beds, wardrobes, desks), and equally when the piece
 * is simply too big or too small for every mesh of that kind — a 2.8 m L-shape
 * sectional, a 2.0 m media console. Scaling the velvet sofa onto a sectional
 * would be a lie told in geometry rather than in words.
 */
export function furnitureAssetFor(
  kind: FurnitureKind,
  widthM: number,
  depthM: number,
  variantIndex = 0,
  assetId?: string,
): FurnitureAsset | null {
  if (assetId) {
    const requested = furnitureAssetById(assetId)
    return requested && requested.serves.includes(kind) && servesFootprint(requested, widthM, depthM)
      ? requested
      : null
  }
  const usable = furnitureAssetsForKind(kind).filter((asset) => servesFootprint(asset, widthM, depthM))
  if (!usable.length) return null
  // An exact footprint match wins: that is the case where the mesh is already
  // the right size and needs no scaling at all.
  const exact = usable.filter(
    (asset) => Math.abs(asset.widthM - widthM) <= 0.02 && Math.abs(asset.depthM - depthM) <= 0.02,
  )
  const pool = exact.length ? exact : usable
  return pool[variantIndex % pool.length]
}
